        {
            std::vector<coord_type> pixelSize;
            im.get_pixel_size(pixelSize);

            std::vector<coord_type> origin;
            im.get_origin(origin);

            axis_type axis;
            im.get_axis(axis);

            this->set_pixel_size(pixelSize);
            this->set_origin(origin);
            this->set_axis(axis);
        }

