namespace Gadgetron::Core {


    class ThreadPool {
    private:
        class Work {
        public:
            virtual void execute() = 0;
            /*
            DPCT1109:15: Virtual functions cannot be called in SYCL device code. You need to adjust the code.
            */
            virtual ~Work() = default;
        };

        template <class F, class... ARGS> class Storage{
        public:
            explicit Storage(F&& f, ARGS&&... args)
                : f{ std::forward<F>(f) }, args{ std::forward<ARGS>(args)... } {}
        protected:
            F f;
            boost::hana::tuple<std::decay_t<ARGS>...> args;
        public:
            using R = decltype(boost::hana::unpack(std::move(args),f));
        protected:
            std::promise<R> promise;


        public:
            std::future<R> get_future() {
                return promise.get_future();
            }
        };
        template<class F, bool IS_VOID, class... ARGS> class ConcreteWorkImpl{};

        template<class F, class... ARGS> class ConcreteWorkImpl<F,false,ARGS...> : public Work, public Storage<F,ARGS...> {
        public:
            using Storage<F,ARGS...>::Storage;

            void execute() override {
                try {
                    auto val = boost::hana::unpack(std::move(this->args),this->f);
                    this->promise.set_value(std::move(val));
                } catch (...){
                    this->promise.set_exception(std::current_exception());
                }
            }
        };
        template<class F, class... ARGS> class ConcreteWorkImpl<F,true,ARGS...> : public Work, public Storage<F,ARGS...> {
        public:
            using Storage<F,ARGS...>::Storage;

            void execute() override {
                try {
                    boost::hana::unpack(std::move(this->args),this->f);
                    this->promise.set_value();
                } catch (...){
                    this->promise.set_exception(std::current_exception());
                }
            }
        };

    template<class F, class... ARGS> class ConcreteWork : public ConcreteWorkImpl<F, std::is_same<typename Storage<F,ARGS...>::R,void>::value,ARGS...> {
        public:
            using ConcreteWorkImpl<F, std::is_same<typename Storage<F,ARGS...>::R,void>::value,ARGS...>::ConcreteWorkImpl;
        };

    public:
        explicit ThreadPool(unsigned int workers) {
            for (auto i = 0u; i < workers; i++) {
                threads.emplace_back([this]() {
                    try {
                        while (true)
                            /*
                            DPCT1109:16: Virtual functions cannot be called in SYCL device code. You need to adjust the
                            code.
                            */
                            this->work_queue.pop()->execute();
                    } catch (const ChannelClosed&) {
                    }
                });
            }
        }

        template <class F, class... ARGS> auto async(F&& f, ARGS&&... args) {
            auto work = std::make_unique<ConcreteWork<F, ARGS...>>(std::forward<F>(f), std::forward<ARGS>(args)...);
            auto future_result = work->get_future();
            work_queue.push(std::move(work));
            return std::move(future_result);
        }

        void join(){
            work_queue.close();
            for (auto& thread : threads){
                thread.join();
            }
        }

    private:
        MPMCChannel<std::unique_ptr<Work>> work_queue;
        std::vector<std::thread> threads;
    };

}
// ===== End: core/ThreadPool.h =====


using namespace Gadgetron::Core;

namespace Gadgetron::Server::Connection::Nodes {

    void ParallelProcess::process_input(GenericInputChannel input, Queue &queue) {

        ThreadPool pool(workers ? workers : std::thread::hardware_concurrency());

        for (auto message : input) {
            queue.push(
                pool.async(
                        [&](auto message) { return pureStream.process_function(std::move(message)); },
                        std::move(message)
                )
            );
        }

        pool.join(); queue.close();
    }

    void ParallelProcess::process_output(OutputChannel output, Queue &queue) {
        while(true) output.push_message(queue.pop().get());
    }

    void ParallelProcess::process(GenericInputChannel input,
            OutputChannel output,
            ErrorHandler& error_handler
    ) {
        Queue queue;

        auto input_thread = error_handler.run(
                [&](auto input) { this->process_input(std::move(input), queue); },
                std::move(input)
        );

        auto output_thread = error_handler.run(
                [&](auto output) { this->process_output(std::move(output), queue); },
                std::move(output)
        );

        input_thread.join(); output_thread.join();
    }

    ParallelProcess::ParallelProcess(
            const Config::ParallelProcess& conf,
            const Context& context,
            Loader& loader
    ) : pureStream{ conf.stream, context, loader }, workers{ conf.workers } {}

    const std::string& ParallelProcess::name() {
        const static std::string n = "ParallelProcess";
        return n;
    }
}


